//! Unicode lookups for the tokenizer (TASK-30): letter (and, since TASK-37, letter
//! case), number, mark, punctuation, symbol and white space classes for the
//! pre-tokenizer patterns, and NFC normalization. Tables are generated by
//! tools/ref/gen_unicode.py.
const std = @import("std");
const tables = @import("unicode_tables.zig");

pub fn isLetter(cp: u21) bool {
    return inRanges(&tables.letters, cp);
}

pub fn isNumber(cp: u21) bool {
    return inRanges(&tables.numbers, cp);
}

/// General category M (combining marks), which Qwen3.5's pattern treats like letters.
pub fn isMark(cp: u21) bool {
    return inRanges(&tables.marks, cp);
}

/// Categories Lu and Lt.
pub fn isUpper(cp: u21) bool {
    return inRanges(&tables.upper, cp);
}

/// Category Ll.
pub fn isLower(cp: u21) bool {
    return inRanges(&tables.lower, cp);
}

/// Categories Lm and Lo, which gpt-oss's pattern counts as both cases.
pub fn isOtherLetter(cp: u21) bool {
    return inRanges(&tables.other_letters, cp);
}

/// General category P.
pub fn isPunctuation(cp: u21) bool {
    return inRanges(&tables.punctuation, cp);
}

/// General category S.
pub fn isSymbol(cp: u21) bool {
    return inRanges(&tables.symbols, cp);
}

/// The White_Space property, which `\s` matches in the tokenizers' regexes.
pub fn isSpace(cp: u21) bool {
    return switch (cp) {
        0x09...0x0D, 0x20, 0x85, 0xA0, 0x1680, 0x2000...0x200A, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000 => true,
        else => false,
    };
}

fn inRanges(rs: []const [2]u21, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = rs.len;
    while (lo < hi)
    {
        const mid = (lo + hi) / 2;
        if (cp < rs[mid][0])
        {
            hi = mid;
        }
        else if (cp > rs[mid][1])
        {
            lo = mid + 1;
        }
        else
        {
            return true;
        }
    }
    return false;
}

fn combiningClass(cp: u21) u8 {
    if (cp < 0x300)
    {
        return 0;
    }
    const rs = &tables.combining;
    var lo: usize = 0;
    var hi: usize = rs.len;
    while (lo < hi)
    {
        const mid = (lo + hi) / 2;
        if (cp < rs[mid][0])
        {
            hi = mid;
        }
        else if (cp > rs[mid][1])
        {
            lo = mid + 1;
        }
        else
        {
            return @intCast(rs[mid][2]);
        }
    }
    return 0;
}

const hangul_s = 0xAC00;
const hangul_l = 0x1100;
const hangul_v = 0x1161;
const hangul_t = 0x11A7;
const hangul_t_count = 28;
const hangul_n = 21 * hangul_t_count;
const hangul_count = 19 * hangul_n;

fn decompose(gpa: std.mem.Allocator, cp: u21, out: *std.ArrayList(u21)) !void {
    if (cp >= hangul_s and cp < hangul_s + hangul_count)
    {
        const s = cp - hangul_s;
        try out.append(gpa, hangul_l + s / hangul_n);
        try out.append(gpa, hangul_v + (s % hangul_n) / hangul_t_count);
        if (s % hangul_t_count != 0)
        {
            try out.append(gpa, hangul_t + s % hangul_t_count);
        }
        return;
    }
    const idx = &tables.decomp_index;
    var lo: usize = 0;
    var hi: usize = idx.len;
    while (lo < hi)
    {
        const mid = (lo + hi) / 2;
        if (cp < idx[mid][0])
        {
            hi = mid;
        }
        else if (cp > idx[mid][0])
        {
            lo = mid + 1;
        }
        else
        {
            try out.appendSlice(gpa, tables.decomp_data[idx[mid][1]..][0..idx[mid][2]]);
            return;
        }
    }
    try out.append(gpa, cp);
}

fn compose(a: u21, b: u21) ?u21 {
    if (a >= hangul_l and a < hangul_l + 19 and b >= hangul_v and b < hangul_v + 21)
    {
        return hangul_s + ((a - hangul_l) * 21 + (b - hangul_v)) * hangul_t_count;
    }
    if (a >= hangul_s and a < hangul_s + hangul_count and (a - hangul_s) % hangul_t_count == 0 and b > hangul_t and b < hangul_t + hangul_t_count)
    {
        return a + (b - hangul_t);
    }
    const ps = &tables.compose;
    var lo: usize = 0;
    var hi: usize = ps.len;
    while (lo < hi)
    {
        const mid = (lo + hi) / 2;
        const p = ps[mid];
        if (a < p[0] or (a == p[0] and b < p[1]))
        {
            hi = mid;
        }
        else if (a > p[0] or b > p[1])
        {
            lo = mid + 1;
        }
        else
        {
            return p[2];
        }
    }
    return null;
}

/// Appends the NFC form of valid UTF-8 `text` to `out`.
pub fn nfc(gpa: std.mem.Allocator, text: []const u8, out: *std.ArrayList(u8)) !void {
    // Text below U+0300 is already in NFC: nothing there combines.
    var simple = true;
    var view = std.unicode.Utf8View.initUnchecked(text).iterator();
    while (view.nextCodepoint()) |cp|
    {
        if (cp >= 0x300)
        {
            simple = false;
            break;
        }
    }
    if (simple)
    {
        try out.appendSlice(gpa, text);
        return;
    }

    var buf: std.ArrayList(u21) = .empty;
    defer buf.deinit(gpa);
    view = std.unicode.Utf8View.initUnchecked(text).iterator();
    while (view.nextCodepoint()) |cp|
    {
        try decompose(gpa, cp, &buf);
    }
    const cps = buf.items;

    // Canonical ordering: sort each run of combining marks by class, stably.
    var i: usize = 1;
    while (i < cps.len)
    {
        const cc = combiningClass(cps[i]);
        if (cc != 0)
        {
            var j = i;
            while (j > 0 and combiningClass(cps[j - 1]) > cc)
            {
                std.mem.swap(u21, &cps[j], &cps[j - 1]);
                j -= 1;
            }
        }
        i += 1;
    }

    // Canonical composition, following the Unicode reference algorithm.
    var len: usize = 0;
    if (cps.len > 0)
    {
        var starter: usize = 0;
        var last_class: u16 = combiningClass(cps[0]);
        if (last_class != 0)
        {
            last_class = 256; // the first character is not a starter, so nothing composes with it
        }
        len = 1;
        for (cps[1..]) |ch|
        {
            const cc = combiningClass(ch);
            if (compose(cps[starter], ch)) |comp|
            {
                if (last_class < cc or last_class == 0)
                {
                    cps[starter] = comp;
                    continue;
                }
            }
            if (cc == 0)
            {
                starter = len;
            }
            last_class = cc;
            cps[len] = ch;
            len += 1;
        }
    }
    for (cps[0..len]) |cp|
    {
        var enc: [4]u8 = undefined;
        const n = std.unicode.utf8Encode(cp, &enc) catch unreachable;
        try out.appendSlice(gpa, enc[0..n]);
    }
}

test "NFC composes, reorders, and handles Hangul" {
    const gpa = std.testing.allocator;
    const cases = [_][2][]const u8{
        .{ "caf\u{65}\u{301}", "caf\u{e9}" },
        .{ "plain ascii", "plain ascii" },
        .{ "\u{1100}\u{1161}\u{11A8}", "\u{AC01}" },
        .{ "a\u{323}\u{302}", "\u{1EAD}" },
        .{ "a\u{302}\u{323}", "\u{1EAD}" },
        .{ "\u{212B}", "\u{C5}" },
        .{ "\u{1E0B}\u{323}", "\u{1E0D}\u{307}" },
    };
    for (cases) |c|
    {
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(gpa);
        try nfc(gpa, c[0], &out);
        try std.testing.expectEqualStrings(c[1], out.items);
    }
}

test "character classes" {
    try std.testing.expect(isLetter('a') and isLetter(0x4E2D) and !isLetter('1'));
    try std.testing.expect(isNumber('7') and isNumber(0x2163) and !isNumber('x'));
    try std.testing.expect(isSpace(' ') and isSpace(0x3000) and !isSpace('_'));
}
